const client = require('prom-client');

const requestCounter = new client.Counter({
  name: 'http_requests_total',
  help: 'Total number of HTTP requests received',
  labelNames: ['route', 'status_code'],
});

const requestDuration = new client.Histogram({
  name: 'http_request_duration_seconds',
  help: 'HTTP request duration in seconds',
  labelNames: ['route', 'status_code'],
  buckets: [0.05, 0.1, 0.2, 0.5, 1, 2, 5],
});

app.get('/api/orders/:id', async (req, res) => {
  const endTimer = requestDuration.startTimer({ route: '/api/orders/:id' });
  try {
    const order = await fetchOrder(req.params.id);
    res.status(200).json(order);
    requestCounter.inc({ route: '/api/orders/:id', status_code: 200 });
  } catch (err) {
    res.status(500).json({ error: 'failed to fetch order' });
    requestCounter.inc({ route: '/api/orders/:id', status_code: 500 });
  } finally {
    endTimer({ status_code: res.statusCode });
  }
});

app.get('/metrics', async (req, res) => {
  res.set('Content-Type', client.register.contentType);
  res.end(await client.register.metrics());
});

